using System.IO;
using UnityEditor;
using UnityEngine;

// (Editor script generated by AI)

// Extracts the Built-in Render Pipeline's default spot light cookie ("Soft.psd", 128x128 Alpha8)
// to a PNG imported as a spot light cookie, so URP spot lights can reproduce the BIRP angular falloff.
// Assign it as the light's Cookie and set Inner Spot Angle equal to Outer, so the cookie alone shapes the edge.
public static class BIRPSpotCookieExtractor
{
    const string k_BuiltinCookieName = "Soft.psd";
    const string k_DefaultPath = "Assets/URP/Cookies/BIRP_DefaultSpotCookie.png";

    [MenuItem("Tools/BIRP to URP/Extract Default Spot Cookie...")]
    static void ExtractWithDialog()
    {
        var dir = Path.GetDirectoryName(k_DefaultPath);
        if (!AssetDatabase.IsValidFolder(dir))
            dir = "Assets";

        var path = EditorUtility.SaveFilePanelInProject("Save BIRP Default Spot Cookie",
            Path.GetFileNameWithoutExtension(k_DefaultPath), "png",
            "Choose where to save the Built-in Render Pipeline default spot cookie.", dir);
        if (string.IsNullOrEmpty(path))
            return;

        var cookie = Extract(path);
        if (cookie != null)
        {
            EditorGUIUtility.PingObject(cookie);
            Selection.activeObject = cookie;
        }
    }

    /// <summary>
    /// Writes the built-in default spot cookie to <paramref name="assetPath"/> (a .png under Assets/)
    /// and imports it as a spot light cookie. Returns the imported texture, or null on failure.
    /// </summary>
    public static Texture2D Extract(string assetPath = k_DefaultPath)
    {
        var source = Resources.GetBuiltinResource<Texture2D>(k_BuiltinCookieName);
        if (source == null)
        {
            Debug.LogError($"Built-in texture '{k_BuiltinCookieName}' not found.");
            return null;
        }
        if (!source.isReadable)
        {
            Debug.LogError($"Built-in texture '{k_BuiltinCookieName}' is not CPU-readable.");
            return null;
        }

        // Mip 0 only. The cookie is single-channel alpha; copy it into every channel so the PNG
        // previews correctly and still works if the importer is later switched to a color format.
        var pixels = source.GetPixels32(0);
        for (int i = 0; i < pixels.Length; i++)
        {
            byte a = pixels[i].a;
            pixels[i] = new Color32(a, a, a, a);
        }

        var copy = new Texture2D(source.width, source.height, TextureFormat.RGBA32, false, true);
        try
        {
            copy.SetPixels32(pixels);
            copy.Apply();

            Directory.CreateDirectory(Path.GetDirectoryName(assetPath));
            File.WriteAllBytes(assetPath, copy.EncodeToPNG());
        }
        finally
        {
            Object.DestroyImmediate(copy);
        }

        AssetDatabase.ImportAsset(assetPath, ImportAssetOptions.ForceUpdate);

        var importer = (TextureImporter)AssetImporter.GetAtPath(assetPath);
        importer.textureType = TextureImporterType.Cookie;
        importer.sRGBTexture = false;
        importer.alphaSource = TextureImporterAlphaSource.FromInput;
        importer.wrapMode = TextureWrapMode.Clamp;
        importer.textureCompression = TextureImporterCompression.Uncompressed;

        var settings = new TextureImporterSettings();
        importer.ReadTextureSettings(settings);
        settings.textureShape = TextureImporterShape.Texture2D;
        settings.singleChannelComponent = TextureImporterSingleChannelComponent.Alpha;
        importer.SetTextureSettings(settings);
        importer.SaveAndReimport();

        var result = AssetDatabase.LoadAssetAtPath<Texture2D>(assetPath);
        Debug.Log($"Extracted BIRP default spot cookie ({source.width}x{source.height}) to {assetPath}", result);
        return result;
    }
}
